cat > /tmp/ivx-soak-monitor.ts << 'SOAK_SCRIPT'
import { writeFileSync, readFileSync, existsSync } from "fs";

const HEALTH_URL = "https://ivx-holdings-platform.onrender.com/health";
const VERSION_URL = "https://ivx-holdings-platform.onrender.com/version";
const CHAT_URL = "https://ivx-holdings-platform.onrender.com/api/chat";
const RESULTS_FILE = "/tmp/ivx-soak-results.json";
const LOG_FILE = "/tmp/ivx-soak-log.txt";
const INTERVAL_MS = 30000; // 30 seconds
const TARGET_DURATION_MS = 2 * 60 * 60 * 1000; // 2 hours

interface SoakState {
  startTime: string;
  endTime: string | null;
  duration: string;
  requestCount: number;
  successCount: number;
  failureCount: number;
  errors4xx: number;
  errors5xx: number;
  timeouts: number;
  restarts: number;
  queueStalls: number;
  databaseFailures: number;
  providerFailures: number;
  coldStartEvents: number;
  latencies: number[];
  p50: number;
  p95: number;
  p99: number;
  maxLatency: number;
  lastBootTime: string | null;
  expectedSha: string;
  shaChanges: number;
  shaMismatches: number;
  samples: Array<{ time: string; status: number; latency: number; healthy: boolean; coldStart: boolean }>;
}

function loadState(): SoakState {
  if (existsSync(RESULTS_FILE)) {
    try {
      return JSON.parse(readFileSync(RESULTS_FILE, "utf8"));
    } catch {
      // corrupt, start fresh
    }
  }
  return {
    startTime: new Date().toISOString(),
    endTime: null,
    duration: "0s",
    requestCount: 0,
    successCount: 0,
    failureCount: 0,
    errors4xx: 0,
    errors5xx: 0,
    timeouts: 0,
    restarts: 0,
    queueStalls: 0,
    databaseFailures: 0,
    providerFailures: 0,
    coldStartEvents: 0,
    latencies: [],
    p50: 0,
    p95: 0,
    p99: 0,
    maxLatency: 0,
    lastBootTime: null,
    expectedSha: "d3b0e0eb685258becd15cef9536e60299ab62d2a",
    shaChanges: 0,
    shaMismatches: 0,
    samples: [],
  };
}

function saveState(s: SoakState) {
  writeFileSync(RESULTS_FILE, JSON.stringify(s, null, 2));
}

function log(msg: string) {
  const line = `[${new Date().toISOString()}] ${msg}`;
  writeFileSync(LOG_FILE, line + "\n", { flag: "a" });
  console.log(line);
}

function calcPercentiles(latencies: number[]): { p50: number; p95: number; p99: number; max: number } {
  if (latencies.length === 0) return { p50: 0, p95: 0, p99: 0, max: 0 };
  const sorted = [...latencies].sort((a, b) => a - b);
  const idx = (p: number) => Math.min(sorted.length - 1, Math.floor(p * sorted.length));
  return {
    p50: sorted[idx(0.5)],
    p95: sorted[idx(0.95)],
    p99: sorted[idx(0.99)],
    max: sorted[sorted.length - 1],
  };
}

async function fetchWithTimeout(url: string, opts: RequestInit = {}, timeoutMs = 15000): Promise<{ status: number; body: string; latency: number; timedOut: boolean }> {
  const start = Date.now();
  try {
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), timeoutMs);
    const res = await fetch(url, { ...opts, signal: ctrl.signal });
    clearTimeout(timer);
    const body = await res.text();
    return { status: res.status, body, latency: Date.now() - start, timedOut: false };
  } catch (e: any) {
    if (e.name === "AbortError") {
      return { status: 0, body: "", latency: Date.now() - start, timedOut: true };
    }
    return { status: 0, body: String(e?.message || e), latency: Date.now() - start, timedOut: false };
  }
}

async function runCycle(state: SoakState): Promise<SoakState> {
  const now = new Date().toISOString();

  // Health check
  const healthRes = await fetchWithTimeout(HEALTH_URL);
  state.requestCount++;

  let isHealthy = false;
  let isColdStart = false;
  let bootTime: string | null = null;
  let dbOk = false;
  let aiOk = false;
  let queueDepth = -1;
  let workerRunning = false;
  let sha = "";

  if (healthRes.status === 200) {
    try {
      const h = JSON.parse(healthRes.body);
      isHealthy = h.status === "healthy";
      bootTime = h.bootTime || null;
      dbOk = h.databaseConfigured === true;
      aiOk = h.ai?.ok === true;
      queueDepth = h.queue?.depth ?? -1;
      workerRunning = h.queue?.workerRunning === true;
      sha = h.commit || "";

      // Check for restart
      if (state.lastBootTime && bootTime && state.lastBootTime !== bootTime) {
        state.restarts++;
        log(`RESTART detected: ${state.lastBootTime} → ${bootTime}`);
      }
      if (bootTime) state.lastBootTime = bootTime;

      // Check SHA
      if (sha && sha !== state.expectedSha) {
        state.shaMismatches++;
        log(`SHA MISMATCH: expected ${state.expectedSha}, got ${sha}`);
      }

      // Queue stall check
      if (queueDepth > 0 && !workerRunning) {
        state.queueStalls++;
        log(`QUEUE STALL: depth=${queueDepth} workerRunning=${workerRunning}`);
      }

      // DB failure
      if (!dbOk) {
        state.databaseFailures++;
        log(`DB FAILURE: databaseConfigured=${dbOk}`);
      }

      // Provider failure
      if (!aiOk) {
        state.providerFailures++;
        log(`PROVIDER FAILURE: ai.ok=${aiOk}`);
      }

      state.successCount++;
      state.latencies.push(healthRes.latency);
    } catch (e) {
      state.failureCount++;
      log(`PARSE ERROR: ${e}`);
    }
  } else if (healthRes.status === 502 || healthRes.status === 503) {
    isColdStart = true;
    state.coldStartEvents++;
    state.errors5xx++;
    state.failureCount++;
    log(`COLD START 5xx: status=${healthRes.status} latency=${healthRes.latency}ms`);
  } else if (healthRes.status >= 500) {
    state.errors5xx++;
    state.failureCount++;
    log(`5xx ERROR: status=${healthRes.status} latency=${healthRes.latency}ms`);
  } else if (healthRes.status >= 400) {
    state.errors4xx++;
    state.failureCount++;
    log(`4xx ERROR: status=${healthRes.status} latency=${healthRes.latency}ms`);
  } else if (healthRes.timedOut) {
    state.timeouts++;
    state.failureCount++;
    log(`TIMEOUT: latency=${healthRes.latency}ms`);
  } else {
    state.failureCount++;
    log(`NETWORK ERROR: ${healthRes.body} latency=${healthRes.latency}ms`);
  }

  // Public chat test (every other cycle to avoid overload)
  if (healthRes.status === 200 && state.requestCount % 2 === 0) {
    try {
      const chatRes = await fetchWithTimeout(CHAT_URL, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ message: "What is 7 multiplied by 8?" }),
      });
      if (chatRes.status === 200) {
        try {
          const chatBody = JSON.parse(chatRes.body);
          if (chatBody.ok !== true) {
            log(`CHAT WARNING: ok=${chatBody.ok}`);
          }
        } catch {}
      } else {
        log(`CHAT ${chatRes.status}: non-200`);
      }
    } catch (e) {
      log(`CHAT ERROR: ${e}`);
    }
  }

  // Record sample (keep last 500)
  state.samples.push({ time: now, status: healthRes.status, latency: healthRes.latency, healthy: isHealthy, coldStart: isColdStart });
  if (state.samples.length > 500) state.samples = state.samples.slice(-500);

  // Update percentiles
  const pct = calcPercentiles(state.latencies);
  state.p50 = pct.p50;
  state.p95 = pct.p95;
  state.p99 = pct.p99;
  state.maxLatency = pct.max;

  // Duration
  const elapsedMs = Date.now() - new Date(state.startTime).getTime();
  state.duration = `${Math.floor(elapsedMs / 1000 / 60)}m ${Math.floor(elapsedMs / 1000) % 60}s`;

  saveState(state);

  // Check completion
  if (elapsedMs >= TARGET_DURATION_MS) {
    state.endTime = new Date().toISOString();
    saveState(state);
    log(`SOAK COMPLETE: duration=${state.duration} requests=${state.requestCount} pass=${state.successCount} fail=${state.failureCount} coldStarts=${state.coldStartEvents} 5xx=${state.errors5xx} timeouts=${state.timeouts} restarts=${state.restarts} queueStalls=${state.queueStalls} dbFail=${state.databaseFailures} providerFail=${state.providerFailures} P50=${state.p50}ms P95=${state.p95}ms P99=${state.p99}ms maxLatency=${state.maxLatency}ms`);
    process.exit(0);
  }

  return state;
}

async function main() {
  const state = loadState();
  log(`SOAK MONITOR STARTED: expectedSha=${state.expectedSha} startTime=${state.startTime}`);

  // If resuming, adjust startTime to maintain continuity
  if (state.requestCount > 0) {
    log(`RESUMING: ${state.requestCount} requests already recorded, duration=${state.duration}`);
  }

  let s = state;
  while (true) {
    try {
      s = await runCycle(s);
    } catch (e) {
      log(`CYCLE ERROR: ${e}`);
    }
    await new Promise(r => setTimeout(r, INTERVAL_MS));
  }
}

main();
SOAK_SCRIPT
echo "Soak monitor script written"

# Launch in background with nohup
nohup bun run /tmp/ivx-soak-monitor.ts > /tmp/ivx-soak-stdout.txt 2>&1 &
SOAK_PID=$!
echo "SOAK_PID=$SOAK_PID"
sleep 3
# Verify it's running
if ps -p $SOAK_PID > /dev/null 2>&1; then
  echo "MONITOR_RUNNING=true"
  echo "PID=$SOAK_PID"
else
  echo "MONITOR_RUNNING=false"
  cat /tmp/ivx-soak-stdout.txt
fi

